// parseDuration is time.ParseDuration extended with a leading days
// component, "d", of 24 hours: "30d", "1.5d" or "1d12h".
func parseDuration(v string) (time.Duration, error) {
	i := strings.IndexByte(v, 'd')
	if i < 0 {
		return time.ParseDuration(v)
	}
	num, rest := v[:i], v[i+1:]
	neg := false
	if num != "" && (num[0] == '+' || num[0] == '-') {
		neg = num[0] == '-'
		num = num[1:]
	}
	if num == "" || strings.Trim(num, "0123456789.") != "" || strings.HasPrefix(rest, "+") || strings.HasPrefix(rest, "-") {
		return 0, fmt.Errorf("invalid duration")
	}
	days, err := strconv.ParseFloat(num, 64)
	if err != nil {
		return 0, err
	}
	const day = 24 * time.Hour
	total := days * float64(day)
	if total >= float64(math.MaxInt64) {
		return 0, fmt.Errorf("duration overflow")
	}
	d := time.Duration(total)
	if rest != "" {
		r, err := time.ParseDuration(rest)
		if err != nil {
			return 0, err
		}
		if d > math.MaxInt64-r {
			return 0, fmt.Errorf("duration overflow")
		}
		d += r
	}
	if neg {
		d = -d
	}
	return d, nil
}
